def inventory():
    entries=[];by_geometry={};aliases={}
    for category,(title,rows) in GROUPS.items():
        for row in rows:
            id,label,recipe,*more=row;more=(more+[None]*4)[:4];tone,badge,arg,slash=more;tone=tone or 'g'
            # Use a real upload badge symbol, not a font glyph.
            if badge=='upload':badge='arrow'
            if badge=='info':badge='alert'
            if badge=='shield':badge='lock'
            key=(recipe,tone,badge,arg,bool(slash))
            if key in by_geometry:
                e=by_geometry[key];e['aliases']+=[id,label];e['categories']=list(dict.fromkeys(e['categories']+[category]));e['usages'].append({'id':id,'label':label,'category':category});aliases[id]=e['id'];continue
            e={'id':id,'label':label,'category':category,'categoryLabel':title,'categories':[category],'recipe':recipe,'tone':tone,'badge':badge,'arg':arg,'slash':bool(slash),'aliases':[],'capabilities':[],'scope':'complement' if category=='editorial' else 'v1-design','purpose':f'{label} — repère visuel pour {title.lower()} dans Zamurek.'}
            e['usages']=[{'id':id,'label':label,'category':category}]
            entries.append(e);by_geometry[key]=e;aliases[id]=id
    byid={e['id']:e for e in entries}
    mapping={}
    for cap,ids in CAP_MAP.items():
        mapping[cap]=list(dict.fromkeys(aliases[id] for id in ids))
        for id in mapping[cap]:byid[id]['capabilities'].append(cap)
    return entries,mapping,aliases
